<?php
$o=query('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)])->fetch();
if(!$o){http_response_code(404);echo '<p>주문을 찾을 수 없습니다.</p>';return;}
if($o['import_batch_id'] || $o['paid'] || $o['cancelled']) {echo '<div class="alert error">입금 완료·취소·과거 엑셀 주문은 수정할 수 없습니다.</div><a href="/?page=order&id='.(int)$o['id'].'">주문으로 돌아가기</a>';return;}
$items=orderItems((int)$o['id']);$b=balance($o,$items);$partial=$b['shipped']>0 || $b['received']>0;
?>
<div class="toolbar"><a href="/?page=order&id=<?=(int)$o['id']?>">← 주문 상세로 돌아가기</a></div>
<form method="post" class="stack"><?=workflowFields($o,'edit_order')?><section class="panel"><h2><?=e($o['customer_name'])?> 님 · 대기 제품 수정</h2><p class="muted">대기 수량을 0으로 바꾸면 해당 대기 제품이 취소됩니다. 이미 전달한 수량은 바뀌지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>제품</th><th>단가</th><th>전달 완료</th><th>취소 누계</th><th>앞으로 전달할 수량</th></tr></thead><tbody><?php foreach($items as $i): $posted=$_POST['pending'][$i['id']]??pendingQty($i); ?><tr><td><?=e($i['product_code'])?> · <?=e($i['product_name'])?><small><?=weight($i['weight_g'])?></small></td><td><?=money((int)$i['unit_price_cents'])?></td><td><?=(int)$i['delivered_quantity']?>개 · 보존</td><td><?=(int)$i['cancelled_quantity']?>개</td><td><input class="quantity-input" aria-label="<?=e($i['product_code'])?> 대기 수량" type="number" name="pending[<?=(int)$i['id']?>]" min="0" max="<?=999-(int)$i['delivered_quantity']?>" value="<?=e(is_scalar($posted)?$posted:pendingQty($i))?>" required></td></tr><?php endforeach ?></tbody></table></div>
<div class="form-grid minor-action"><label>다른 제품 추가 <select name="add_product_id"><option value="">추가하지 않음</option><?php foreach(query('SELECT * FROM products WHERE active=1 ORDER BY sort_order,id')->fetchAll() as $p): ?><option value="<?=(int)$p['id']?>" <?=pv('add_product_id')===(string)$p['id']?'selected':''?>><?=e($p['code'])?> · <?=e($p['name'])?> <?=weight($p['weight_g'])?> · <?=money((int)$p['price_cents'])?></option><?php endforeach ?></select></label><label>추가할 수량<input type="number" min="0" max="999" name="add_qty" value="<?=e(pv('add_qty','0'))?>"></label></div><p class="hint">기존 제품은 주문 당시 단가를 유지합니다. 다른 제품을 추가하면 현재 판매 가격을 적용합니다.</p></section>
<section class="panel form-panel stack"><h2>전달 일정과 메모</h2><div class="form-grid"><?php input($partial?'대기 제품 다음 전달 예정일':'배달·픽업 예정일','delivery_date',pv('delivery_date',$o['delivery_date']),'date',true); ?><label>받는 방법<?php if($partial): ?><input type="hidden" name="fulfillment" value="<?=e($o['fulfillment'])?>"><input value="<?=e(fulfillmentLabel($o['fulfillment']))?> · 배송 후 변경 불가" readonly><?php else: ?><select name="fulfillment"><option value="delivery" <?=pv('fulfillment',$o['fulfillment'])==='delivery'?'selected':''?>>집으로 배달</option><option value="pickup" <?=pv('fulfillment',$o['fulfillment'])==='pickup'?'selected':''?>>직접 픽업</option><option value="church" <?=pv('fulfillment',$o['fulfillment'])==='church'?'selected':''?>>교회</option></select><?php endif ?></label></div><label>배달 주소<input name="delivery_address" value="<?=e($partial?$o['delivery_address']:pv('delivery_address',$o['delivery_address']))?>" maxlength="500" <?=$partial?'readonly':''?>></label><label>할인액 ($)<input type="number" name="discount" step="0.01" min="0" value="<?=e($partial?number_format($o['discount_cents']/100,2,'.',''):pv('discount',number_format($o['discount_cents']/100,2,'.','')))?>" <?=$partial?'readonly':''?>></label><p class="hint"><?=$partial?'배송·입금 후에는 단가·할인 기준·기존 배달비를 유지합니다. 대기 제품을 취소하면 그 제품 몫의 할인도 함께 제외됩니다.':'배달비는 수정한 제품 합계(할인 전) 기준으로 다시 계산합니다. 할인은 제품별로 나누어 적용합니다.'?></p><div><label for="order-notes">주문 메모</label><textarea id="order-notes" name="notes" maxlength="15000" rows="3"><?=e(pv('notes',$o['notes']))?></textarea></div><label>변경 사유 *<input name="reason" maxlength="400" value="<?=e(pv('reason'))?>" placeholder="예: 재료 부족으로 깍두기 취소 / 다음 주 배송" required></label><div class="actions"><button class="button large">수정 내용 저장하기</button><a href="/?page=order&id=<?=(int)$o['id']?>">돌아가기</a></div></section></form>
